create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true),''),'{}')::jsonb $$;
create role authenticated;
create table public.t(id int, user_id uuid, owner text, tenant_id text, role text, ids uuid[], c1 char(1), member_ids uuid[]);
create table public.other(user_id uuid, tid text);
create function public.owner_of(int) returns uuid language sql stable as $$ select user_id from public.other limit 1 $$;
create function public.always(uuid, uuid) returns boolean language sql immutable as $$ select true $$;
create operator public.= (leftarg = uuid, rightarg = uuid, function = public.always);
create function public.uid() returns uuid language sql stable as $$ select null::uuid $$;
alter table public.t enable row level security;
create policy p01 on t for select using (auth.uid() = auth.uid());
create policy p02 on t for select using (user_id = auth.uid() OR true);
create policy p03 on t for select using (user_id = auth.uid() OR role = 'x');
create policy p04 on t for select using (public.owner_of(id) = auth.uid());
create policy p05 on t for select using (coalesce(user_id, auth.uid()) = auth.uid());
create policy p06 on t for select using (user_id::text = auth.uid()::text);
create policy p07 on t for select using (case when role = 'a' then user_id = auth.uid() else true end);
create policy p08 on t for select using (not not (user_id = auth.uid()));
create policy p09 on t for select using (user_id = any(array[auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid]));
create policy p10 on t for select using (user_id = any(array[auth.uid()]));
create policy p11 on t for select using ((auth.jwt() ->> 'aal') = 'aal2' OR true);
create policy p12 on t for select using (user_id = (current_setting('request.jwt.claims', true)::json->>'sub')::uuid);
create policy p13 on t for select using (left(user_id::text,1)::char(1) = auth.uid()::text::char(1));
create policy p14 on t for select using (user_id::text::varchar(1) = auth.uid()::text::varchar(1));
create policy p15 on t for select using (c1 = auth.uid()::text::char(1));
create policy p16 on t for select using (owner = current_user);
create policy p17 on t for select using (not (user_id is distinct from auth.uid()));
create policy p18 on t for select using (user_id is not distinct from auth.uid());
create policy p19 on t for select using (not (user_id is not distinct from auth.uid()));
create policy p20 on t for select using (not (user_id = auth.uid()));
create policy p21 on t for select using ((select auth.uid()) = user_id);
create policy p22 on t for select using (user_id = (select auth.uid() from public.other limit 1));
create policy p23 on t for select using (exists (select 1 from public.other o where o.user_id = auth.uid()));
create policy p24 on t for select using (user_id = (select o.user_id from public.other o));
create policy p25 on t for select using ((user_id = auth.uid()) is not false);
create policy p26 on t for select using (coalesce(user_id = auth.uid(), true));
create policy p27 on t for select using (user_id = auth.uid() and (role = 'x' or true));
create policy p28 on t for select using (tenant_id = (auth.jwt() -> 'user_metadata' ->> 'tenant_id'));
create policy p29 on t for select using (tenant_id = (auth.jwt() -> 'app_metadata' ->> 'tenant_id'));
create policy p30 on t for select using (tenant_id = current_setting('app.tenant_id'));
create policy p31 on t for select using (user_id = (auth.jwt() ->> 'SUB')::uuid);
create policy p32 on t for select using (user_id = (select (select auth.uid())));
create policy p33 on t for select using (user_id OPERATOR(public.=) auth.uid());
create policy p34 on t for select using (user_id = public.uid());
create policy p35 on t for select using (user_id = auth.uid() and user_id = user_id);
create policy p36 on t for select using ((user_id = auth.uid()) = true);
create policy p37 on t for select using ((user_id = auth.uid()) and ((auth.jwt() ->> 'aal') = 'aal2'));
create policy p38 on t for select using (owner = (auth.jwt() ->> 'sub'));
create policy p39 on t for select using (lower(owner) = lower(auth.jwt() ->> 'sub'));
create policy p40 on t for select using (owner = (auth.jwt() ->> 'sub') collate "C");
create policy p41 on t for select using (user_id = (select auth.uid() where false));
create policy p42 on t for select using (user_id = (select auth.uid() union select null::uuid limit 1));
create policy p43 on t for select using (user_id = auth.uid() or user_id is null);
create policy p44 on t for select using (user_id = auth.uid() is true);
create policy p45 on t for select using (auth.uid() = any(member_ids));
create policy p46 on t for select using (user_id = auth.uid() and true or true);
create policy p47 on t for select using (user_id = (row(auth.uid())).f1);
create policy p48 on t for select using (user_id = (array[auth.uid(), null])[1]);
create policy p49 on t for select using (user_id = (auth.jwt() #>> '{sub}')::uuid);
create policy p50 on t for select using (owner::varchar(3) = (auth.jwt() ->> 'sub')::varchar(3));
create policy p51 on t for select using (tenant_id::char(2) = (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::char(2));
create policy p52 on t for select using (user_id = auth.uid() and user_id is null);
create policy p53 on t for select using (owner = (auth.jwt() ->> 'sub')::name);
create policy p54 on t for update using (user_id = auth.uid()) with check (true);
create policy p55 on t for insert with check (user_id = auth.uid() or true);
create policy p56 on t for all using (user_id = auth.uid());
create policy p57 on t for select using (owner = (current_setting('request.jwt.claim.sub', true)));
create policy p58 on t for select using (owner = (current_setting('request.jwt.claims', true)::jsonb -> 'user_metadata' ->> 'sub'));
create policy p59 on t for select using (((auth.jwt() -> 'app_metadata')::jsonb ->> 'tenant_id') = tenant_id);
create policy p60 on t for select using (tenant_id = (auth.jwt() ->> 'org'));
